package org.apache.commons.csv;

import java.io.Serializable;
import java.util.Arrays;
import java.util.Iterator;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

public class CSVRecord_5_4Test {

    @Test
    public void testisMapped_mappingIsNull() throws Exception {
        CSVRecord record = new CSVRecord(new String[]{"value1"}, null, null, 1);
        Assertions.assertEquals(false, record.isMapped("name"), "Expected mapping to be null, so isMapped should return false");
    }

    @Test
    public void testisMapped_nameExistsInMapping() throws Exception {
        Map<String, Integer> mapping = new HashMap<>();
        mapping.put("name", 0);
        CSVRecord record = new CSVRecord(new String[]{"value1"}, mapping, null, 1);
        Assertions.assertEquals(true, record.isMapped("name"), "Expected name to exist in mapping, so isMapped should return true");
    }

    @Test
    public void testisMapped_nameDoesNotExistInMapping() throws Exception {
        Map<String, Integer> mapping = new HashMap<>();
        mapping.put("otherName", 0);
        CSVRecord record = new CSVRecord(new String[]{"value1"}, mapping, null, 1);
        Assertions.assertEquals(false, record.isMapped("name"), "Expected name to not exist in mapping, so isMapped should return false");
    }

    @Test
    public void testisMapped_emptyMapping() throws Exception {
        Map<String, Integer> mapping = Collections.emptyMap();
        CSVRecord record = new CSVRecord(new String[]{"value1"}, mapping, null, 1);
        Assertions.assertEquals(false, record.isMapped("name"), "Expected empty mapping, so isMapped should return false");
    }

    @Test
    public void testisMapped_nullName() throws Exception {
        Map<String, Integer> mapping = new HashMap<>();
        mapping.put("name", 0);
        CSVRecord record = new CSVRecord(new String[]{"value1"}, mapping, null, 1);
        Assertions.assertEquals(false, record.isMapped(null), "Expected null name to return false");
    }

    @Test
    public void testisMapped_emptyStringName() throws Exception {
        Map<String, Integer> mapping = new HashMap<>();
        mapping.put("name", 0);
        CSVRecord record = new CSVRecord(new String[]{"value1"}, mapping, null, 1);
        Assertions.assertEquals(false, record.isMapped(""), "Expected empty string name to return false");
    }

    @Test
    public void testisMapped_caseSensitiveName() throws Exception {
        Map<String, Integer> mapping = new HashMap<>();
        mapping.put("Name", 0);
        CSVRecord record = new CSVRecord(new String[]{"value1"}, mapping, null, 1);
        Assertions.assertEquals(false, record.isMapped("name"), "Expected name to be case-sensitive, so isMapped should return false");
    }

    @Test
    public void testisMapped_nonExistentNameInNonEmptyMapping() throws Exception {
        Map<String, Integer> mapping = new HashMap<>();
        mapping.put("name", 0);
        mapping.put("anotherName", 1);
        CSVRecord record = new CSVRecord(new String[]{"value1", "value2"}, mapping, null, 1);
        Assertions.assertEquals(false, record.isMapped("nonExistentName"), "Expected non-existent name to return false");
    }
}
